class Counter:
    def __init__(self):
        self.count = 0

    def add(self, n):
        self.count += n

c = Counter()
c.add(2)
Counter.add(c, 3)
print(c.count)
# 5

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def describe(self):
        return f"{self.width} x {self.height}, area {self.area()}"

print(Rectangle(3, 4).describe())
# 3 x 4, area 12

class Dog:
    def __init__(self, name):
        self.name = name

print(Dog("Rex"))
# <__main__.Dog object at 0x00000265B1BF5010>

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

    def intro(self):
        return f"{self.name} says {self.speak()}"

class Dog(Animal):
    def speak(self):               # overrides the parent's version
        return "Woof"

class Cat(Animal):
    def speak(self):
        return "Meow"

for pet in [Dog("Rex"), Cat("Tom"), Animal("Thing")]:
    print(pet.intro())
# Rex says Woof
# Tom says Meow
# Thing says ...

class Account:
    def __init__(self, balance):
        self._balance = balance

    @property
    def balance(self):             # getter: obj.balance
        return self._balance

    @balance.setter
    def balance(self, value):      # setter: obj.balance = value
        if value < 0:
            raise ValueError("balance cannot be negative")
        self._balance = value

a = Account(100)
a.balance = 250
print(a.balance)
try:
    a.balance = -5
except ValueError as e:
    print("Error:", e)
# 250
# Error: balance cannot be negative

class Dog:
    count = 0

    def __init__(self, name, age):
        self.name = name
        self.age = age
        Dog.count += 1

    @classmethod
    def from_string(cls, text):          # alternative constructor
        name, age = text.split(",")
        return cls(name, int(age))

    @staticmethod
    def is_valid_age(age):
        return 0 <= age <= 30

rex = Dog.from_string("Rex,3")
print(rex.name, rex.age)
print(Dog.is_valid_age(45))
print(Dog.count)
# Rex 3
# False
# 1

